import re

def cmp_semver(a, b):
    def parse(version):
        # Remove build metadata
        main_part = version.split('+')[0]
        # Split version into main and pre-release
        parts = main_part.split('-')
        main_version_str = parts[0]
        pre_release_str = parts[1] if len(parts) > 1 else None

        # Parse major.minor.patch
        main_parts = [int(x) for x in main_version_str.split('.')]
        # Ensure we have 3 parts even if missing
        while len(main_parts) < 3:
            main_parts.append(0)

        pre_release = []
        if pre_release_str is not None:
            for item in pre_release_str.split('.'):
                if item.isdigit():
                    pre_release.append(int(item))
                else:
                    pre_release.append(item)

        return main_parts, pre_release

    v1_main, v1_pre = parse(a)
    v2_main, v2_pre = parse(b)

    # Compare major, minor, patch
    for i in range(3):
        if v1_main[i] < v2_main[i]:
            return -1
        if v1_main[i] > v2_main[i]:
            return 1

    # Pre-release logic
    # A version WITH a pre-release sorts BEFORE the same version without one
    if v1_pre is not None and v2_pre is None:
        return -1
    if v1_pre is None and v2_pre is not None:
        return 1
    if v1_pre is None and v2_pre is None:
        return 0

    # Both have pre-releases, compare them
    for p1, p2 in zip(v1_pre, v2_pre):
        if type(p1) != type(p2):
            # Numeric identifiers sort before alphanumeric ones
            return -1 if isinstance(p1, int) else 1
        if p1 < p2:
            return -1
        if p1 > p2:
            return 1

    # Longer identifier list wins
    if len(v1_pre) < len(v2_pre):
        return -1
    if len(v1_pre) > len(v2_pre):
        return 1

    return 0
