                            results.add(v)
                else:
                    val = int(base)
                    if (val - val) % step == 0: # Always true for single number
                        results.add(val)
            elif '-' in part:
                s_str, e_str = part.split('-')
                results.update(range(int(s_str), int(e_str) + 1))
            else:
                results.add(int(part))

        final = set()
        for r in results:
            if min_val <= r <= max_val:
                final.add(r)
        return sorted(list(final))

    try:
        # Fields: min, hour, dom, month, dow
        # Limits: min(0-59), hour(0-23), dom(1-31), month(1-12), dow(0-6)
