        hour_list = parse_field(parts[1], 0, 23)
        dom_list = parse_field(parts[2], 1, 31)
        month_list = parse_field(parts[3], 1, 12)
        dow_list = parse_field(parts[4], 0, 6)
    except ValueError as e:
        raise ValueError(f"Malformed expression: {e}")

