    current = (after + relativedelta(minutes=1)).replace(second=0, microsecond=0)

    # Optimization: Jump to the next valid month/hour/min if possible
    # But for simplicity and correctness with complex rules, we iterate.
    # To handle the "OR" rule for DOM and DOW:
    # If both are restricted, it's (DOM matches OR DOW matches).
    # If only one is restricted, it's that one.
    # If neither is restricted, it's any day.

    # We limit the search to a reasonable range (e.g., 2 years) to prevent infinite loops
    for _ in range(1000 * 24 * 60):
