           current.hour in hour_list and \
           current.month in month_list:

            dom_match = current.day in dom_list
            dow_match = (current.weekday() + 1) % 7 in dow_list # dateutil weekday 0=Mon, so 0=Sun is (wd+1)%7
            # Wait, standard cron 0=Sun. dateutil.relativedelta/datetime.weekday() 0=Mon.
            # Let's use datetime.strftime('%w') which is 0=Sun.
            dow_val = int(current.strftime('%w'))
            dow_match = dow_val in dow_list

            dom_restricted = len(dom_list) < 31
            dow_restricted = len(dow_list) < 7

            valid = False
            if dom_restricted and dow_restricted:
                if dom_match or dow_match:
                    valid = True
            elif dom_restricted:
                if dom_match:
                    valid = True
            elif dow_restricted:
                if dow_match:
                    valid = True
            else:
                valid = True

            if valid:
                return current

        current += relativedelta(minutes=1)
        if current.year > after.year + 2: break

    raise ValueError("No fire time found in reasonable range.")
