async function toposortTasks(tasks) {
  const results = new Map();
  const status = new Map(); // 'pending', 'running', 'completed', 'failed'
  const promises = new Map();
  let firstError = null;

  const executeTask = async (name) => {
    if (status.get(name) === 'completed') return results.get(name);
    if (status.get(name) === 'running') return promises.get(name);
    if (status.get(name) === 'failed') throw firstError;

    status.set(name, 'running');
    const task = tasks[name];

    try {
      const depValues = {};
      for (const depName of task.deps) {
        if (!(depName in tasks)) {
          throw new Error(`Missing dependency: ${depName}`);
        }
        depValues[depName] = await executeTask(depName);
      }

      const value = await task.run(depValues);
      results.set(name, value);
      status.set(name, 'completed');
      return value;
    } catch (err) {
      if (!firstError) firstError = err;
      status.set(name, 'failed');
      throw err;
    }
  };

  const visited = new Set();
  const stack = new Set();

  const checkCycle = (name) => {
    if (stack.has(name)) throw new Error(`Cycle detected involving: ${name}`);
    if (visited.has(name)) return;

    visited.add(name);
    stack.add(name);

    const task = tasks[name];
    if (task) {
      for (const dep of task.deps) {
        if (!(dep in tasks)) throw new Error(`Missing dependency: ${dep}`);
        checkCycle(dep);
      }
    }
    stack.delete(name);
  };

  try {
    for (const name in tasks) {
      checkCycle(name);
    }
  } catch (err) {
    if (err.message.includes('Cycle')) throw err;
    throw err;
  }

  const finalPromises = Object.keys(tasks).map(name => {
    promises.set(name, executeTask(name));
    return promises.get(name);
  });

  try {
    await Promise.allSettled(finalPromises);
    if (firstError) throw firstError;
    return Object.fromEntries(results);
  } catch (err) {
    if (firstError) throw firstError;
    throw err;
  }
}

module.exports = toposortTasks;
